CURLcode generate_plain_auth_message(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t total_len = user_len + pass_len + 2; // user\0pass\0
  size_t b64_len = Curl_base64_encode(data, NULL, total_len, NULL);

  if (!b64_len) {
    return CURLE_OUT_OF_MEMORY;
  }

  char *b64 = malloc(b64_len);
  if (!b64) {
    return CURLE_OUT_OF_MEMORY;
  }

  // Construct the PLAIN message (user\0pass\0)
  char *plain = malloc(total_len);
  if (!plain) {
    free(b64);
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);
  plain[total_len - 1] = '\0';

  // Encode the PLAIN message to Base64
  CURLcode result = Curl_base64_encode(data, plain, total_len, &b64);

  free(plain);

  if (result != CURLE_OK) {
    free(b64);
    return result;
  }

  *outptr = b64;
  *outlen = b64_len;

  return CURLE_OK;
}

CURLcode base64_plain_auth(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t total_len = user_len + 1 + pass_len + 1;
  size_t encoded_len = Curl_base64_encode(data, NULL, total_len, NULL);
  char *plain = NULL;
  char *encoded = NULL;
  CURLcode result = CURLE_OK;

  if (!userp || !passwdp) {
    return CURLE_BAD_FUNCTION_ARGUMENT;
  }

  plain = malloc(total_len);
  if (!plain) {
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);
  plain[user_len + 1 + pass_len] = '\0';

  encoded = malloc(encoded_len);
  if (!encoded) {
    free(plain);
    return CURLE_OUT_OF_MEMORY;
  }

  result = Curl_base64_encode(data, plain, total_len, encoded, &encoded_len);
  if (result != CURLE_OK) {
    free(plain);
    free(encoded);
    return result;
  }

  *outptr = encoded;
  *outlen = encoded_len;

  free(plain);
  return CURLE_OK;
}

CURLcode base64_plain_auth(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t total_len = user_len + pass_len + 2; // user\0, pass\0
  size_t encoded_len;
  char *message = NULL;
  char *encoded = NULL;
  CURLcode result = CURLE_OK;

  if(!userp || !passwdp || !outptr || !outlen) {
    return CURLE_BAD_FUNCTION_ARGUMENT;
  }

  // Allocate memory for the PLAIN message (user\0, pass\0)
  message = malloc(total_len);
  if(!message) {
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(message, userp, user_len);
  message[user_len] = '\0';
  memcpy(message + user_len + 1, passwdp, pass_len);
  message[user_len + 1 + pass_len] = '\0';

  // Calculate the Base64 encoded length
  encoded_len = Curl_base64_encode(data, message, total_len, &encoded, 0);
  if(encoded_len == 0 || !encoded) {
    free(message);
    return CURLE_OUT_OF_MEMORY;
  }

  // Set output pointer and length
  *outptr = encoded;
  *outlen = encoded_len;

  free(message);
  return result;
}

CURLcode Curl_auth_negotiate_plain(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t passwd_len = strlen(passwdp);
  size_t plain_len = user_len + 1 + passwd_len + 1;
  size_t encoded_len = Curl_base64_encode_size(plain_len);
  char *plain = NULL;
  char *encoded = NULL;
  CURLcode result = CURLE_OUT_OF_MEMORY;

  plain = malloc(plain_len);
  if (!plain) {
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, passwd_len);
  plain[user_len + 1 + passwd_len] = '\0';

  encoded = Curl_base64_encode(data, plain, plain_len);
  if (encoded) {
    *outptr = encoded;
    *outlen = encoded_len;
    result = CURLE_OK;
  }

  free(plain);
  return result;
}

CURLcode Curl_auth_create_plain_message(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t total_len = user_len + pass_len + 2; // User + NUL + password
  size_t base64_len = Curl_base64_encode(data, "", 0, NULL, total_len);
  char *plain_message;
  CURLcode result = CURLE_OK;

  // Allocate memory for the PLAIN message
  plain_message = (char *)malloc(total_len);
  if (!plain_message) {
    return CURLE_OUT_OF_MEMORY;
  }

  // Construct the PLAIN message
  memcpy(plain_message, userp, user_len);
  plain_message[user_len] = '\0';
  memcpy(plain_message + user_len + 1, passwdp, pass_len);
  plain_message[user_len + 1 + pass_len] = '\0';

  // Base64 encode the PLAIN message
  result = Curl_base64_encode(data, plain_message, total_len, outptr, base64_len);
  if (result != CURLE_OK) {
    free(plain_message);
    return result;
  }

  *outlen = base64_len;
  free(plain_message);
  return CURLE_OK;
}
